"""Renders the Telegraf config for the Internet module's ping and DNS probes.

Telegraf runs with --watch-config poll, so writing the file is enough to apply it.
"""

from __future__ import annotations

import json
import os

from . import valid_host


def _list(values: list[str]) -> str:
    return json.dumps([v for v in values if valid_host(v)])


def render(settings: dict, site: str) -> str:
    parts = [
        "# Generated by homewatch. Edits are overwritten; change settings in the web page instead.",
        "[agent]",
        '  interval = "30s"',
        "  round_interval = true",
        '  flush_interval = "10s"',
        "  omit_hostname = true",
        "  skip_processors_after_aggregators = true",
        "",
        "[global_tags]",
        f"  site = {json.dumps(site)}",
        "",
        "[[outputs.influxdb]]",
        '  urls = ["http://victoriametrics:8428"]',
        '  database = "homewatch"',
        "  skip_database_creation = true",
        "",
        "# keeps Telegraf valid when every probe is switched off; also shows the agent is alive",
        "[[inputs.internal]]",
        "  collect_memstats = false",
        '  namepass = ["internal_agent"]',
    ]
    pub, gw, dns = settings["public"], settings["gateway"], settings["dns"]
    if pub["enabled"] and pub["targets"]:
        parts += _ping(pub["targets"], "public")
    if gw["enabled"] and gw["target"]:
        parts += _ping([gw["target"]], "gateway")
    if dns["enabled"] and dns["server"] and valid_host(dns["server"]) and valid_host(dns["domain"]):
        parts += [
            "",
            "[[inputs.dns_query]]",
            '  interval = "60s"',
            f"  servers = {_list([dns['server']])}",
            f"  domains = {_list([dns['domain']])}",
            '  record_type = "A"',
            "  timeout = \"2s\"",
            "  # one series per server/domain: result and rcode would split it when lookups start failing",
            '  tagexclude = ["result", "rcode"]',
            "  [inputs.dns_query.tags]",
            '    role = "resolver"',
        ]
    return "\n".join(parts) + "\n"


def _ping(targets: list[str], role: str) -> list[str]:
    return [
        "",
        "[[inputs.ping]]",
        f"  urls = {_list(targets)}",
        '  method = "native"',
        "  count = 5",
        "  ping_interval = 1.0",
        "  deadline = 10",
        "  [inputs.ping.tags]",
        f'    role = "{role}"',
    ]


def write(path_dir: str, text: str) -> bool:
    """Write atomically; return True when the content changed."""
    os.makedirs(path_dir, exist_ok=True)
    path = os.path.join(path_dir, "telegraf.conf")
    try:
        with open(path) as f:
            if f.read() == text:
                return False
    except FileNotFoundError:
        pass
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        f.write(text)
    os.chmod(tmp, 0o644)
    os.replace(tmp, path)
    return True
